   y+=.01/6*(v+2*(v+.005*a)+2*(v+.005*b)+(v+.01*c));v+=.01/6*(a+2*b+2*c+d)
   if abs(y)>1000 or abs(v)>1000: y=1000.;v=1000.
   out[z+1]=y
  start+=n
 return out
results=[]
for mode in range(8):
 p0=np.array([-109.8,-1.652,27.895,-.66,-20.667,.1,4.125,0.,2.])
